import{_ as d,o as e,c as a,ag as r}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Part 13 — AWS (the depth ladder)","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_13_AWS.md","filePath":"todo/study_plan/parts/Part_13_AWS.md"}'),s={name:"todo/study_plan/parts/Part_13_AWS.md"};function i(o,t,n,l,c,p){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="part-13-—-aws-the-depth-ladder" tabindex="-1">Part 13 — AWS (the depth ladder) <a class="header-anchor" href="#part-13-—-aws-the-depth-ladder" aria-label="Permalink to &quot;Part 13 — AWS (the depth ladder)&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 7 (solo — dense, but you operate AWS daily so many rows likely Done already). <strong>Budget: ~10-12 hrs.</strong></p></blockquote><h2 id="_13-aws-—-topic-inventory" tabindex="-1">13 AWS — topic inventory <a class="header-anchor" href="#_13-aws-—-topic-inventory" aria-label="Permalink to &quot;13 AWS — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>EC2 — instance families, EBS, AMIs, user data, instance metadata</td><td>🔴 💼</td><td>MP</td><td>1 hr 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: <code>aws ec2 describe-instances</code> + <code>aws ec2 run-instances</code> from CLI (15 min)</td></tr><tr><td>2</td><td>Auto Scaling Groups — launch templates, scaling policies, lifecycle hooks</td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Lambda — concurrency, cold starts, layers, destinations, provisioned concurrency</td><td>🔴 💼</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: deploy a basic Java Lambda via SAM CLI + invoke (30 min)</td></tr><tr><td>4</td><td>S3 — storage classes, lifecycle, versioning, replication, event notifications</td><td>🔴 💼</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>S3 — strong read-after-write consistency (post-2020), prefix scaling</td><td>🔴 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>EBS — types (gp3, io2), snapshots</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>RDS — Multi-AZ vs read replicas, parameter groups, automated backups</td><td>🔴 💼</td><td>D</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Aurora — storage-decoupled architecture, replicas, Global Database</td><td>🔴 💼</td><td>D</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>DynamoDB — partition keys, GSI, LSI, capacity modes, DAX</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>VPC — subnets (public/private), route tables, IGW, NAT GW</td><td>🔴 💼</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Security groups vs NACLs</td><td>🔴 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>ALB vs NLB vs CLB vs Gateway LB</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Route 53 — routing policies, health checks</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 11 Route 53)</td></tr><tr><td>14</td><td>CloudFront — origins, behaviors, OAC, signed URLs / cookies</td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>IAM — users, groups, roles, policies, trust relationships</td><td>🔴 💼 🔐</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write IAM policy granting S3 read on one bucket + use Condition for source-IP restriction (20 min)</td></tr><tr><td>16</td><td>IAM — policy evaluation logic, permission boundaries, SCPs</td><td>🔴 💼 🔐</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>STS, AssumeRole, role chaining</td><td>🔴 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>KMS — CMKs, data keys, envelope encryption, key policies, grants</td><td>🔴 💼 🔐</td><td>D</td><td>3 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: <code>aws kms encrypt/decrypt</code> via CLI on a small payload + understand the wrap-data-key flow (20 min)</td></tr><tr><td>19</td><td>Secrets Manager vs Parameter Store</td><td>🔴 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>CloudWatch — metrics, logs (Logs Insights), alarms, dashboards</td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>21</td><td>X-Ray — distributed tracing, service map</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>22</td><td>Cost Explorer, Budgets</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>23</td><td>Reserved Instances vs Savings Plans vs Spot vs On-Demand</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>24</td><td>SQS — queue types (Standard vs FIFO), DLQ + redrive, visibility timeout, long polling, message attributes</td><td>🔴 💼 🎯</td><td>MP</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: send/receive messages via AWS CLI; configure DLQ + redrive policy; observe visibility timeout (20 min)</td></tr><tr><td>25</td><td>SNS — topics, subscriptions, fanout, FIFO topics, message filtering</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>26</td><td>API Gateway — REST vs HTTP API, throttling, usage plans, Lambda authorizers, request/response mapping</td><td>🔴 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>27</td><td>ECS vs EKS vs Fargate</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>28</td><td>EFS, FSx</td><td>🟠 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>29</td><td>S3 — pre-signed URLs, Transfer Acceleration</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>30</td><td>ElastiCache (Redis, Memcached)</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>31</td><td>OpenSearch (managed Elasticsearch)</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>32</td><td>RDS Proxy (for Lambda)</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>33</td><td>VPC Peering, Transit Gateway, PrivateLink, Site-to-Site (S2S) VPN — encrypted tunnel between two networks; why internal-LB IPs are private and unreachable from outside the VPC; calling AWS LBs by <code>*.elb.amazonaws.com</code> hostname rather than raw IP</td><td>🟠 💼</td><td>MP</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>34</td><td>Endpoint services (Interface vs Gateway endpoints)</td><td>🟠 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>35</td><td>EventBridge — schema registry, rules, targets, audit / event bus pattern</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>36</td><td>Step Functions — standard vs express workflows, state types, error handling, KYC orchestration fit</td><td>🟠 💼 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>37</td><td>ACM — public + private CAs</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 17 PKI)</td></tr><tr><td>38</td><td>CloudHSM</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>39</td><td>GuardDuty — threat detection, finding types</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>40</td><td>Security Hub — aggregator + compliance standards (CIS, PCI)</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>41</td><td>Inspector — vulnerability assessment for EC2/ECR</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>42</td><td>Macie — S3 data classification, PII discovery</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>43</td><td>WAF, Shield (Standard vs Advanced)</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>44</td><td>Cognito — User Pools vs Identity Pools, federated identity</td><td>🟠 💼 🔐</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>45</td><td>CloudTrail — management &amp; data events, multi-region trail</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>46</td><td>CloudFormation — templates, stacks, change sets, drift</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>47</td><td>CDK (TypeScript / Python)</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>48</td><td>Systems Manager (SSM) — Session Manager, Patch Manager, Run Command</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>49</td><td>AppConfig — feature flags, configuration profiles, gradual rollout, validators</td><td>🟠 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>50</td><td>Organizations — OUs, SCPs, consolidated billing</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>51</td><td>Tagging strategy for cost allocation</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>52</td><td>IAM Identity Center (formerly SSO)</td><td>🟡 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>53</td><td>Detective, Audit Manager</td><td>🟡 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>54</td><td>Managed Grafana, Managed Prometheus</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>55</td><td>Batch</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~51.25 hrs</td><td>~4.7 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~85.5 hrs</td><td>~7.8 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~88.75 hrs</td><td>~8.1 wk</td><td></td></tr></tbody></table><blockquote><p>AWS is dense — you already operate much of it daily, so expect significant ✅ Done at Survey time. Actual study likely 30-50% of zero-baseline estimates.</p></blockquote><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>KMS envelope encryption flow:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant App as Application</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant KMS as KMS (CMK never leaves)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as Storage (DB / S3)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over App,DB: Encrypt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;KMS: GenerateDataKey(CMK)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    KMS--&gt;&gt;App: Plaintext data key + Encrypted data key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;App: Encrypt payload with plaintext data key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;App: Discard plaintext data key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;DB: Store (encrypted payload + encrypted data key)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over App,DB: Decrypt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;DB: Read (encrypted payload + encrypted data key)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;KMS: Decrypt(encrypted data key, CMK)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    KMS--&gt;&gt;App: Plaintext data key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;App: Decrypt payload with plaintext data key</span></span></code></pre></div><blockquote><p>Envelope encryption = encrypt data with a fast symmetric DEK; encrypt the DEK with KMS CMK. Lets you encrypt huge payloads without sending them to KMS. CMK never leaves KMS.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through KMS envelope encryption. Why not encrypt the data directly with the CMK? <ul><li><strong>Why asked:</strong> KYC-canonical security. CMK is for small data (&lt; 4KB) and key-wrapping. Envelope: generate data key, encrypt big payload locally with data key, encrypt only the data key with CMK. Solves: (1) bulk data encryption cost, (2) CMK throughput limits, (3) data key rotation independent of CMK rotation.</li></ul></li><li><strong>Q:</strong> Multi-AZ vs read replicas in RDS — when do you use each? <ul><li><strong>Why asked:</strong> Senior architecture. Multi-AZ: synchronous standby for HA (automatic failover, ~60-120s). Same region, different AZ. Read replicas: async replication for read scaling. Same or different region. You can have both: Multi-AZ for failover, replicas for read offload. KYC platform likely uses both: Multi-AZ for primary, replicas for analytics queries.</li></ul></li><li><strong>Q:</strong> Walk through IAM policy evaluation when a user has both an Allow and a Deny. <ul><li><strong>Why asked:</strong> Senior IAM literacy. Explicit Deny wins. Order: (1) start with implicit Deny, (2) check for explicit Deny → if found, stop, denied. (3) check for explicit Allow → if found, allowed. (4) otherwise, implicit Deny. Plus: SCPs at org level can restrict even if account-level allows. Permission boundaries cap maximum permissions.</li></ul></li><li><strong>Q:</strong> S3 prefix scaling — what&#39;s the trap with high-velocity uploads? <ul><li><strong>Why asked:</strong> Operational knowledge. S3 supports 3500 PUT/COPY/POST/DELETE and 5500 GET/HEAD per second <em>per prefix</em>. If you upload with prefix <code>2026/05/16/HH/MM/...</code>, you&#39;re hot-spotting on the date prefix. Solution: random prefix (hash of object name) or partition keys evenly.</li></ul></li><li><strong>Q:</strong> Design KMS key rotation for your KYC document encryption. <ul><li><strong>Why asked:</strong> Practical security design. CMK with automatic annual rotation. Old DEKs remain decryptable (KMS keeps key versions). Re-encryption of stored data is a separate decision. For high-compliance: rotate CMK every 90 days, re-encrypt old documents as background job.</li></ul></li><li><strong>Q:</strong> VPC design for your KYC platform — public vs private subnets, NAT GW placement? <ul><li><strong>Why asked:</strong> Architecture. Public subnets: ALB, NAT Gateway. Private subnets: EC2/ECS workloads (no direct internet, NAT GW for egress). Database subnets: RDS, even more isolated. NAT GW per AZ for HA. Use VPC endpoints for AWS services to skip NAT (cost saving).</li></ul></li><li><strong>Q:</strong> ALB vs NLB — pick one for your KYC platform, defend. <ul><li><strong>Why asked:</strong> Practical LB choice. ALB: L7, path-based routing, WebSocket, gRPC, HTTPS termination. NLB: L4, ultra-low-latency, static IP, TCP/UDP, source IP preservation. KYC: probably ALB for the SDK ingress (HTTPS termination + path routing); NLB for any TCP-based internal services.</li></ul></li><li><strong>Q:</strong> SQS Standard vs FIFO — when each? <ul><li><strong>Why asked:</strong> Messaging-canonical decision. Standard: at-least-once delivery, best-effort ordering, virtually unlimited throughput, possible duplicates. FIFO: strict ordering per message-group-id, exactly-once-processing (via deduplication ID, 5-min window), 300 msg/s default per API action (3000 with batching, higher with high-throughput mode). FIFO costs more and throttles harder. KYC use case: FIFO when a partner expects strict event order (e.g., document lifecycle events per applicant — <code>UPLOADED</code> → <code>OCR_DONE</code> → <code>VERIFIED</code> must arrive in order). Standard when out-of-order is OK and consumers are idempotent (e.g., webhook fanout, telemetry, audit ingestion). Default to Standard + idempotent consumers; reach for FIFO only when ordering is actually a contract.</li></ul></li><li><strong>Q:</strong> Step Functions for KYC orchestration — when does it fit vs your existing Java orchestrator? <ul><li><strong>Why asked:</strong> Senior architecture call. Step Functions wins for: visual workflow (state machine diagram), built-in retry / catch / backoff per state, long-running waits (up to 1 year for Standard, including human-approval <code>WaitForTaskToken</code>), serverless cost (pay per state transition), native AWS service integrations, automatic execution history. Loses for: vendor lock-in (rewriting in another cloud is painful), debugging complexity (state machine JSON is verbose, errors live in the execution console not your logs), language constraint (Amazon States Language is JSON, not Java — Lambda steps do the real work but glue is JSON), per-state-transition cost at scale. KYC fit: probably overkill for the synchronous SDK happy-path (sub-second p99, in-process Java orchestration is faster and debuggable). Good fit for async compliance review queues (manual reviewer steps, multi-day SLAs, retries on partner outages, branching by risk score).</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your Lambda has a hot-path that occasionally takes 5 seconds. P50 is 100ms. What&#39;s likely happening? <ul><li><strong>Gotcha:</strong> Cold starts. JVM Lambdas can take 3-5s on cold start. Mitigations: (1) provisioned concurrency (pre-warmed instances), (2) smaller runtime (Java → Node/Python), (3) SnapStart for Java 11+, (4) keep functions warm with scheduled invocations (less recommended).</li></ul></li><li><strong>Q:</strong> Your S3 bucket policy allows <code>s3:GetObject</code> from &quot;*&quot;. A bucket-level ACL also blocks public access. Who wins? <ul><li><strong>Gotcha:</strong> Public access block wins. AWS introduced &quot;Block Public Access&quot; settings at bucket and account level that OVERRIDE bucket policies. Even an Allow policy can&#39;t bypass them. Common confusion source.</li></ul></li><li><strong>Q:</strong> You attached <code>AdministratorAccess</code> policy to a role. The role can do everything... except what? <ul><li><strong>Gotcha:</strong> SCPs at organization level can restrict. Permission boundaries on the role can cap. So <code>AdministratorAccess</code> can still be denied by SCP (e.g., &quot;no us-east-1 operations&quot; at the org level). Explicit Deny anywhere wins.</li></ul></li><li><strong>Q:</strong> You&#39;re using NAT Gateway for private subnet egress. Why is your bill so high? <ul><li><strong>Gotcha:</strong> NAT GW charges per GB processed ($0.045/GB) PLUS hourly. High-throughput services through NAT (e.g., large file uploads to a non-AWS API) get expensive fast. Mitigations: (1) VPC endpoints for AWS services, (2) per-AZ NAT GW to skip cross-AZ data transfer.</li></ul></li><li><strong>Q:</strong> Your SQS queue has visibility timeout = 30s. Your consumer takes 60s to process each message. What happens? <ul><li><strong>Gotcha:</strong> After 30s the message becomes visible again → a second consumer picks it up → the same message is processed twice (at minimum). The first consumer&#39;s eventual <code>DeleteMessage</code> succeeds, but the second consumer&#39;s processing has already happened. Result: silent duplicate processing, hard to spot without metrics. Fixes (pick by constraint): (a) reduce processing time below the timeout, (b) increase visibility timeout to comfortably exceed P99 processing latency, (c) call <code>ChangeMessageVisibility</code> periodically from the consumer (heartbeat pattern) so long-running messages stay invisible, (d) accept that duplicates can happen and make the consumer idempotent (deduplication key, upsert semantics, conditional writes). Idempotency (d) is the only fix that survives consumer crashes and partial failures — the others reduce the probability but don&#39;t eliminate it.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>IAM policy evaluation + permission boundaries</strong> (~3 hrs combined rows 15+16) — senior-canonical AWS topic. Build a worked example with multiple policies, SCPs, boundaries; walk through evaluation.</li><li><strong>KMS envelope encryption end-to-end</strong> (~3 hrs row 18) — directly your KYC platform. Encrypt KYC documents with envelope encryption, walk through key rotation, audit access via CloudTrail.</li><li><strong>VPC design for KYC platform</strong> (~3 hrs combined rows 10+11+12+13+14) — public/private subnets, security groups vs NACLs, ALB/NLB choice, Route 53 routing. Document for cross-region (DC-JKT vs AWS-SG).</li><li><strong>DynamoDB partition key design + hot partition mitigation</strong> (~2.5 hrs row 9) — directly common architecture decision. Tie to your KYC vendor result storage if applicable.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up AWS exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>IAM policy review</strong> (~45 min) — given 3 policies (one with <code>Allow</code>, one with <code>Deny</code>, one as SCP), walk through evaluation for 5 sample API calls. Build the mental model for IAM evaluation order.</li><li><strong>CloudFormation / CDK stack from scratch</strong> (~60 min) — write a CDK app (Python or TS) that provisions: VPC + 2 public subnets + 2 private subnets + 1 NAT Gateway. Deploy + tear down. Compare to writing the same in CloudFormation YAML.</li><li><strong>Lambda cold start observation</strong> (~45 min) — deploy a Java Lambda with <code>Runtime.JAVA_17</code>. Invoke 10x consecutively. Capture P99 vs P50 from CloudWatch. Enable provisioned concurrency. Re-test.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Design KMS key strategy for KYC documents</strong> (~90 min) — per-customer-tenant CMK, envelope encryption for documents, key policy granting access only to specific IAM roles, automatic rotation every year, CloudTrail audit. Write it up as if briefing security team.</li><li><strong>VPC design for multi-region KYC</strong> (~90 min) — DC-JKT + AWS-SG regions, public/private subnets, NAT per AZ, VPC peering or Transit Gateway for cross-region, RDS Multi-AZ, ALB with health checks. Document subnet CIDRs, security group rules, Route 53 failover.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~3 hrs</td><td>~0.27 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.5 hrs</strong></td><td><strong>~0.5 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~105 min for Part 13 across 5 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. IAM policy evaluation — what wins, Allow or Deny?</strong> A. Explicit Deny wins. Evaluation order: implicit Deny → explicit Deny (stop if found) → explicit Allow → otherwise implicit Deny. SCPs further restrict at org level. Permission boundaries cap the maximum.</p><p><strong>Q. Multi-AZ vs read replicas?</strong> A. Multi-AZ = sync standby for HA (automatic failover, ~60-120s). Read replicas = async copies for read scaling. Not the same purpose — often use both.</p><p><strong>Q. Envelope encryption — one-line summary?</strong> A. Encrypt payload locally with a fast symmetric data key. Encrypt the data key with KMS CMK. Store both. CMK never sees the payload, allowing efficient bulk encryption.</p><p><strong>Q. S3 prefix scaling — what&#39;s the limit?</strong> A. 3500 PUT/POST/DELETE and 5500 GET/HEAD per prefix per second. Hot-spotting on a common prefix (e.g., date-based) causes throttling. Distribute writes across prefixes for high throughput.</p><p><strong>Q. NAT Gateway cost gotcha?</strong> A. Per-GB data charges ($0.045/GB) plus hourly. High-throughput egress through NAT bills heavily. Use VPC endpoints for AWS services, per-AZ NAT for cross-AZ avoidance.</p><p><strong>Q. ALB vs NLB — pick one for HTTPS termination + path routing.</strong> A. ALB (L7). NLB is L4 (TCP/UDP), preserves source IP, ultra-low latency, but no path routing or HTTPS termination beyond TLS passthrough.</p>`,33)])])}const g=d(s,[["render",i]]);export{u as __pageData,g as default};
